{
  "name": "context-workflow-guard",
  "version": "1.0.0",
  "type": "module",
  "main": "index.js",
  "description": "Context water-level injection, compact relay, the wf_compact tool, and a one-time general-subagent confirmation gate, paired with the context-workflow skill",
  "scripts": {
    "test": "node --test tests/*.test.js"
  },
  "opencode": {
    "type": "plugin",
    "hooks": [
      "tool",
      "event",
      "tool.execute.before",
      "tool.execute.after",
      "experimental.chat.messages.transform",
      "experimental.session.compacting"
    ]
  },
  "license": "MIT",
  "author": "Thexinyi",
  "repository": {
    "type": "git",
    "url": "https://github.com/Thexinyi/context-workflow.git"
  },
  "homepage": "https://github.com/Thexinyi/context-workflow#readme",
  "bugs": {
    "url": "https://github.com/Thexinyi/context-workflow/issues"
  },
  "keywords": [
    "opencode",
    "context-management",
    "workflow",
    "compact",
    "long-running-task",
    "session-binding"
  ]
}
